6	import { makeRenderer, W, H } from './render.js';
7	import { makeAudio } from './audio.js';
8	import { makeUI } from './ui.js';
9	
10	const DT = 1 / 60;
11	const SLS = 'sls2.';
12	const STORE = { stars: SLS + 'stars', unlocked: SLS + 'unlocked', best: SLS + 'best', total: SLS + 'total', mute: SLS + 'mute' };
13	const AUTOTEST = new URLSearchParams(location.search).has('autotest');
14	const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
15	
16	// ==================== state ====================
17	let mode = 'title';            // title | play | end
18	let paused = false, noAuto = false, testMode = false;
19	let levelN = 1;
20	let level, pl;
21	let lives = 3, shards = 0, levelTime = 0;
22	let deathT = 0, levelDone = false, completeDelay = 0;
23	let respawnPoint = { x: 0, y: 0 }, lastCheckpoint = -1;
24	let camX = 0, camY = 0;
25	let visualT = 0, hitstop = 0, shakeT = 0, shakeAmp = 0;
26	let particles = [], floats = [], trail = [];
27	let starsByLevel = {}, unlocked = 1, totalStars = 0, best = 0, muted = false;
28	let reportTarget = null;
29	const reports = [];
30	let lastProgressT = -99;
31	let lastFrame = 0, acc = 0, hiddenPause = false;
32	let simGrab = false, simDir = 0, simReel = 0;
33	let mouseDown = false;
34	let autoGrabT = 0;
35	const keys = new Set(), pressed = new Set();
36	
37	// DOM / systems
38	const canvas = document.getElementById('gl');
39	const renderer = makeRenderer(canvas);
40	const audio = makeAudio();
41	const ui = makeUI({
42	  onStart: () => startFromTitle(),
43	  onLevel: (n) => { if (n <= unlocked) startLevel(n); },
44	  onRetry: () => startLevel(levelN),
45	  onNext: () => { if (levelN < LEVEL_COUNT) startLevel(levelN + 1); else toTitle(); },
46	  onHome: () => toTitle(),
47	  onMute: () => toggleMute(),
48	  onPause: () => togglePause(),
49	  onRestart: () => restartLevel(),
50	});
51	
52	function bootAudio() {
53	  if (AUTOTEST) return;
54	  try {
55	    if (navigator.userActivation && !navigator.userActivation.hasBeenActive) return;
56	  } catch (e) { }
57	  audio.ensure();
58	}
59	
60	// ==================== storage ====================
61	function loadProgress() {
62	  starsByLevel = {};
63	  try {
64	    const raw = JSON.parse(localStorage.getItem(STORE.stars) || '{}');
65	    for (let i = 1; i <= LEVEL_COUNT; i++) {
66	      const v = Number(raw && raw[i]);
67	      if (Number.isInteger(v) && v >= 0 && v <= 3) starsByLevel[i] = v;
68	    }
69	  } catch (e) { }
70	  try { unlocked = clamp(parseInt(localStorage.getItem(STORE.unlocked) || '1', 10) || 1, 1, LEVEL_COUNT); } catch (e) { unlocked = 1; }
71	  recalcTotal();
72	  try { best = Math.max(totalStars, parseInt(localStorage.getItem(STORE.best) || '0', 10) || 0); } catch (e) { best = totalStars; }
73	  try { muted = localStorage.getItem(STORE.mute) === '1'; } catch (e) { muted = false; }
74	}
75	function recalcTotal() {
76	  totalStars = 0;
77	  for (let i = 1; i <= LEVEL_COUNT; i++) totalStars += starsByLevel[i] || 0;
78	}
79	function saveProgress() {
80	  try {
81	    localStorage.setItem(STORE.stars, JSON.stringify(starsByLevel));
82	    localStorage.setItem(STORE.unlocked, String(unlocked));
83	    localStorage.setItem(STORE.best, String(best));
84	    localStorage.setItem(STORE.total, String(totalStars));
85	  } catch (e) { }
86	}
87	function storageSnapshot() {
88	  const o = {};
89	  for (const k of Object.values(STORE)) { try { o[k] = localStorage.getItem(k); } catch (e) { o[k] = null; } }
90	  return o;
91	}
92	function restoreStorage(snap) {
93	  for (const k of Object.values(STORE)) {
94	    try {
95	      if (!snap || snap[k] == null) localStorage.removeItem(k);
96	      else localStorage.setItem(k, snap[k]);
97	    } catch (e) { }
98	  }
99	  loadProgress();
100	  ui.setMute(muted);
101	  audio.setMuted(muted);
102	}
103	loadProgress();
104	audio.setMuted(muted);
105	ui.setMute(muted);
106	
107	// ==================== protocol bridge ====================
108	function toWireReport(frame) {
109	  const score = Number.isFinite(frame.score) ? Math.round(frame.score) : undefined;
110	  if (frame.kind === 'progress') return { kind: 'progress', data: { ...frame } };
111	  if (frame.kind === 'event') return { kind: 'event', event: String(frame.event || frame.tag || 'event'), data: { ...frame } };
112	  if (frame.kind === 'gameOver') return {
113	    kind: 'gameOver', score,
114	    progress: (frame.progress && typeof frame.progress === 'object') ? frame.progress : { value: frame.progress },
115	    data: { ...frame },
116	  };
117	  if (frame.kind === 'complete') return { kind: 'complete', score };
118	  return frame;
119	}
120	function report(kind, payload = {}) {
121	  const frame = { kind, ...payload };
122	  reports.push(frame);
123	  try {
124	    if (reportTarget) reportTarget(frame);
125	    else if (window.parent !== window) {
126	      window.parent.postMessage({ source: 'lightgame', type: 'lightgame:report', payload: toWireReport(frame) }, '*');
127	      if (frame.kind === 'ready') {
128	        window.parent.postMessage({ source: 'lightgame', type: 'lightgame:ready', gameId: 'silkline-swing', v: 1 }, '*');
129	      }
130	    }
131	  } catch (e) { }
132	}
133	report('ready', { game: 'silkline-swing', version: '1.0.0' });
134	
135	// ==================== scoring ====================
136	function scoreNow() {
137	  return Math.round(totalStars * 100 + levelN * 3 + shards * 10);
138	}
139	
140	// ==================== level flow ====================
141	function startFromTitle() {
142	  bootAudio();
143	  audio.sfx.ui();
144	  const n = clamp(unlocked, 1, LEVEL_COUNT);
145	  startLevel(n);
146	}
147	function startLevel(n) {
148	  bootAudio();
149	  levelN = clamp(n | 0, 1, LEVEL_COUNT);
150	  level = instantiateLevel(levelN);
151	  pl = makePlayer(level);
152	  lives = 3; shards = 0; levelTime = 0;
153	  deathT = 0; levelDone = false; completeDelay = 0;
154	  hitstop = 0; shakeT = 0; shakeAmp = 0; autoGrabT = 0;
155	  respawnPoint = { x: level.start.x, y: level.start.y };
156	  lastCheckpoint = -1;
157	  particles = []; floats = []; trail = [];
158	  camX = clamp(pl.x - W * 0.4, 0, Math.max(0, level.worldW - W));
159	  camY = 0;
160	  mode = 'play'; paused = false;
161	  simGrab = false; simDir = 0; simReel = 0; mouseDown = false;
162	  keys.clear(); pressed.clear();
163	  ui.showTitle(false); ui.showEnd(false); ui.showHud(true); ui.setPause(false);
164	  ui.showTouch(ui.isTouch()); ui.setPause(false);
165	  ui.el.guide.style.display = '';
166	  ui.hideBanner();
167	  ui.setHud({ chapter: `第${['一', '二', '三'][level.chapter - 1]}章 · ${level.chapterName}`, name: level.name, level: levelN, shards: 0, lives: 3, time: 0, totalStars });
168	  ui.banner(`第 ${levelN} 关 · ${level.name}`, `收齐 3 颗星屑 · 穿过星门`, 1900);
169	  audio.state('play');
170	  report('event', { event: 'levelStart', level: levelN, score: scoreNow() });
171	}
172	function toTitle() {
173	  mode = 'title'; paused = false; deathT = 0; levelDone = false;
174	  keys.clear(); pressed.clear(); simGrab = false; mouseDown = false;
175	  ui.showTitle(true, progressSnapshot(), clamp(unlocked, 1, LEVEL_COUNT));
176	  ui.showHud(false); ui.showEnd(false); ui.hideBanner(); ui.setPause(false);
177	  ui.showTouch(false);
178	  ui.el.guide.style.display = 'none';
179	  audio.state('calm');
180	  if (!level) { level = instantiateLevel(1); pl = makePlayer(level); }
181	}
182	function progressSnapshot() {
183	  recalcTotal();
184	  return { starsByLevel: { ...starsByLevel }, unlocked, totalStars, best };
185	}
186	function restartLevel() {
187	  if (mode === 'title') return;
188	  audio.sfx.ui();
189	  ui.toast('重开本关');
190	  startLevel(levelN);
191	}
192	function nextLevelAfterEnd() {
193	  if (levelN < LEVEL_COUNT) startLevel(levelN + 1);
194	  else toTitle();
195	}
196	
197	function completeLevel() {
198	  if (mode !== 'play' || levelDone) return;
199	  levelDone = true; mode = 'end';
200	  const stars = ratingFor(level, shards, levelTime);
201	  const prev = starsByLevel[levelN] || 0;
202	  if (stars > prev) starsByLevel[levelN] = stars;
203	  unlocked = Math.max(unlocked, Math.min(LEVEL_COUNT, levelN + 1));
204	  recalcTotal();
205	  if (totalStars > best) best = totalStars;
206	  saveProgress();
207	  const sc = scoreNow();
208	  report('progress', { score: sc, progress: levelN, level: levelN, stars, shards, time: +levelTime.toFixed(1) });
209	  report('event', { event: 'levelClear', level: levelN, stars, score: sc });
210	  let allClear = true;
211	  for (let i = 1; i <= LEVEL_COUNT; i++) if (!(starsByLevel[i] >= 1)) { allClear = false; break; }
212	  if (levelN === LEVEL_COUNT || allClear) report('complete', { score: sc });
213	  audio.sfx.gate(); audio.state('win');
214	  addShake(10, 0.5);
215	  burst(pl.x, pl.y, 36, '#ffd08a', 320, 1.0);
216	  burst(level.gate.x, level.gate.y, 26, '#b6ffe8', 220, 0.9);
217	  ui.showHud(false);
218	  ui.setPause(false);
219	  ui.endPanel({
