      const ap = anchorPos(a, pl.t);
      pl.L = clamp(Math.hypot(pl.x - ap.x, pl.y - ap.y), 120, 260);
      autoGrabT = 0.6;
    }
  }
  camX = clamp(pl.x - W * 0.4, 0, Math.max(0, level.worldW - W));
