// ==================== main loop ====================
function frame(now) {
  requestAnimationFrame(frame);
  if (!lastFrame) lastFrame = now;
  let dt = (now - lastFrame) / 1000;
  lastFrame = now;
  if (!isFinite(dt) || dt < 0) dt = 0;
  dt = Math.min(dt, 0.1);
  if (!testMode) {
    acc += dt;
    let steps = 0;
    while (acc >= DT && steps < 5) { update(DT); acc -= DT; steps++; }
    if (acc > DT * 5) acc = 0;
  }
  render();
}
