1	// Silkline Swing — DOM UI layer: HUD, title level grid, end panel, touch pad.
2	import { LEVELS } from './levels.js';
3	
4	export function makeUI(cb) {
5	  const $ = (id) => document.getElementById(id);
6	  const el = {
7	    hud: $('hud'), chapter: $('hud-chapter'), level: $('hud-level'),
8	    shards: $('hud-shards'), lives: $('hud-lives'), time: $('hud-time'), total: $('hud-total'),
9	    mute: $('mutebtn'), pause: $('pausebtn'), restart: $('restartbtn'),
10	    title: $('title'), grid: $('level-grid'), titleBest: $('title-best'), start: $('startbtn'),
11	    end: $('end'), endKick: $('end-kicker'), endHead: $('end-heading'), endReason: $('end-reason'),
12	    endStars: $('end-stars'), endShards: $('end-shards'), endTime: $('end-time'), endTotal: $('end-total'),
13	    endNext: $('end-next'), endRetry: $('end-retry'), endHome: $('end-home'),
14	    banner: $('banner'), bmain: document.querySelector('#banner .bmain'), bsub: document.querySelector('#banner .bsub'),
15	    toast: $('toast'), flash: $('flash'), guide: $('guide'), touch: $('touch'),
16	    grab: $('tgrab'), left: $('tleft'), right: $('tright'), tin: $('tin'), tout: $('tout'),
17	  };
18	
19	  el.start.addEventListener('click', () => cb.onStart());
20	  el.endNext.addEventListener('click', () => cb.onNext());
21	  el.endRetry.addEventListener('click', () => cb.onRetry());
22	  el.endHome.addEventListener('click', () => cb.onHome());
23	  el.mute.addEventListener('click', () => cb.onMute());
24	  el.pause.addEventListener('click', () => cb.onPause());
25	  el.restart.addEventListener('click', () => cb.onRestart());
26	
27	  // --- level grid (built once, refreshed on progress changes) ---
28	  const levelButtons = [];
29	  for (let ch = 0; ch < 3; ch++) {
30	    const wrap = document.createElement('div');
31	    wrap.className = 'chap';
32	    const t = document.createElement('div');
33	    t.className = 'ctitle';
34	    t.textContent = `第 ${['一', '二', '三'][ch]} 章 · ${LEVELS[ch * 6].chapterName}`;
35	    wrap.appendChild(t);
36	    for (let i = ch * 6; i < ch * 6 + 6; i++) {
37	      const b = document.createElement('button');
38	      b.className = 'lv';
39	      b.innerHTML = `<div class="n">第 ${i + 1} 关</div><div class="nm">${LEVELS[i].name}</div><div class="st">◇◇◇</div>`;
40	      b.addEventListener('click', () => cb.onLevel(i + 1));
41	      wrap.appendChild(b);
42	      levelButtons.push(b);
43	    }
44	    el.grid.appendChild(wrap);
45	  }
46	
47	  let bannerTimer = 0, toastTimer = 0;
48	  function banner(main, sub = '', ms = 1500) {
49	    el.bmain.textContent = main;
50	    el.bsub.textContent = sub;
51	    el.banner.classList.add('show');
52	    clearTimeout(bannerTimer);
53	    if (ms > 0) bannerTimer = setTimeout(() => el.banner.classList.remove('show'), ms);
54	  }
55	  function hideBanner() { el.banner.classList.remove('show'); clearTimeout(bannerTimer); }
56	  function toast(text, ms = 1800) {
57	    el.toast.textContent = text;
58	    el.toast.classList.add('show');
59	    clearTimeout(toastTimer);
60	    toastTimer = setTimeout(() => el.toast.classList.remove('show'), ms);
61	  }
62	  function flash(on) {
63	    el.flash.classList.toggle('on', !!on);
64	    if (on) setTimeout(() => el.flash.classList.remove('on'), 220);
65	  }
66	
67	  function renderGrid(progress, current) {
68	    const { starsByLevel, unlocked } = progress;
69	    for (let i = 0; i < 18; i++) {
70	      const b = levelButtons[i];
71	      const n = i + 1;
72	      const locked = n > unlocked;
73	      b.classList.toggle('locked', locked);
