}
report('ready', { game: 'echo-hour', version: '1.0.0' });

// ==================== score / flow ====================
function scoreNow() { return Math.max(0, Math.round(levelScore + levelN * 10)); }
function allCleared() {
  for (let i = 1; i <= LEVEL_COUNT; i++) if (!(starsByLevel[i] >= 1)) return false;
  return true;
}
function progressSnapshot() {
