  ui.showHud(false); ui.setPause(false); ui.hideBanner();
  ui.endPanel({
    kick: levelN === LEVEL_COUNT ? 'ECHO HOUR COMPLETE' : 'ECHO RESTORED',
    heading: levelN === LEVEL_COUNT ? '双时之门已开' : '时门已渡',
