  echoActive = true; echoT = 0; echoPrevIdx = -1; echoTrail = [];
  echoPos = { x: +x, y: +y, facing };
  return true;
}
function clearEcho() {
  echoActive = false; echoFrames = []; echoT = 0; echoPos = null; echoTrail = []; echoPrevIdx = -1;
}

// ==================== rewind ====================
function isRewindHeld() {
