    sim.rewind || ui.touchState().rewind;
}
function makeSnapshot() {
  return {
    x: pl.x, y: pl.y, vx: pl.vx, vy: pl.vy, onGround: pl.onGround,
    facing: pl.facing, coyote: pl.coyote, jumpBuf: pl.jumpBuf,
    mechT: level.mechT, time: levelTime,
